const MAX_BODY_BYTES = 16 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  sendJson(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Use ${allow}.`);
}

/** Returns a header as one string. Repeated headers are joined, which fails any strict format check. */
function headerValue(req: IncomingMessage, name: string): string | undefined {
  const value = req.headers[name];
  return Array.isArray(value) ? value.join(', ') : value;
}

function isJsonContentType(value: string | undefined): boolean {
  if (value === undefined) return false;
  return (value.split(';', 1)[0] ?? '').trim().toLowerCase() === 'application/json';
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function handleCreate(db: DatabaseSync, req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];
  const keyHeader = headerValue(req, 'idempotency-key');
  if (keyHeader !== undefined) {
    const keyError = validateIdempotencyKey(keyHeader);
    if (keyError) errors.push(keyError);
  }

  const { text, tooLarge } = await readBody(req);
  let submission: JobSubmission | undefined;
  if (!isJsonContentType(headerValue(req, 'content-type'))) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (tooLarge) {
    errors.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    let parsedOk = false;
    try {
      parsed = JSON.parse(text);
      parsedOk = true;
    } catch {
      errors.push({ field: 'body', message: 'is not valid JSON' });
    }
    if (parsedOk) {
      const result = validateSubmission(parsed);
      if (result.ok) submission = result.value;
      else errors.push(...result.errors);
    }
