}

export type ValidationResult = { ok: true; value: JobSubmission } | { ok: false; errors: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_INPUT_LENGTH = 1000;

export function validateIdempotencyKey(key: string): FieldError | undefined {
  return IDEMPOTENCY_KEY_PATTERN.test(key)
