function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Validates a parsed request body. Every offending field is reported, not just the first. */
export function validateSubmission(body: unknown): ValidationResult {
  if (!isRecord(body)) return { ok: false, errors: [{ field: 'body', message: 'must be a JSON object' }] };

  const errors: FieldError[] = [];
  for (const name of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(name)) errors.push({ field: name, message: 'unknown field' });
  }
  const get = (name: string): unknown => (Object.hasOwn(body, name) ? body[name] : undefined);

  let input = '';
