  const failAttempts = integerField(get, 'failAttempts', 0, 5, 0, errors);

  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, value: { input, steps, failAttempts } };
}

function integerField(
  get: (name: string) => unknown,
  name: string,
  min: number,
  max: number,
  fallback: number,
  errors: FieldError[],
): number {
  const raw = get(name);
  if (raw === undefined) return fallback;
  if (typeof raw !== 'number' || !Number.isInteger(raw)) {
    errors.push({ field: name, message: 'must be an integer' });
  } else if (raw < min || raw > max) {
    errors.push({ field: name, message: `must be between ${min} and ${max}` });
  } else {
    return raw;
  }
  return fallback;
}
